activity_ratio_by_country = Customers.WHERE(
    (YEAR(join_date) == 2022) & (HAS(transactions_made) == 1)
).PARTITION(
    name="country_groups", by=(country)
).CALCULATE(
    country=country,
    AR=IFF(
        COUNT(Customers) > 0,
        (COUNT(Customers.WHERE(LOWER(status) == 'active')) * 100.0) / COUNT(Customers),
        0.0
    )
)

activity_ratio_by_country = Customers.WHERE(
    (YEAR(join_date) == 2022) & (HAS(transactions_made) == 1)
).CALCULATE(
    country=country,
    is_active=(LOWER(status) == 'active')
).PARTITION(name="country_groups", by=country).CALCULATE(
    country=country,
    active_customers=SUM(Customers.is_active),
    total_customers_with_transactions=COUNT(Customers)
).CALCULATE(
    country=country,
    AR=IFF(total_customers_with_transactions > 0, (100.0 * active_customers) / total_customers_with_transactions, 0.0)
)

